/**
 * Typed access to the homepage content snapshot.
 *
 * The snapshot is generated by `scripts/sync-home-snapshot.mjs` from the live
 * site and must not be hand-edited: the client requires the copy to stay
 * word-for-word identical. This module validates its shape at build time and
 * groups sections by role so the UI never matches on raw strings.
 */
import "server-only";
import { z } from "zod";
import { resolveSitePath } from "./routes";
import snapshot from "./home.snapshot.json";

const PLACEHOLDER_IMAGE = "/media/home/placeholder-image.png";

/** The live site shows a grey placeholder for cards without a photo; treat those as "no image". */
const imageSchema = z
  .string()
  .nullable()
  .transform((src) => (src && src !== PLACEHOLDER_IMAGE ? src : null));

const tourCardSchema = z.object({
  title: z.string().min(1),
  href: z.string().min(1),
  image: imageSchema,
  duration: z.string().optional(),
  price: z.string().optional(),
});

const destinationSchema = z.object({
  title: z.string().min(1),
  href: z.string().min(1),
  image: imageSchema,
});

const textLinkSchema = z.object({ label: z.string().min(1), href: z.string().min(1) });

const sectionSchema = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("cards"), title: z.string(), items: z.array(tourCardSchema).min(1) }),
  z.object({ kind: z.literal("destinations"), title: z.string(), items: z.array(destinationSchema).min(1) }),
  z.object({ kind: z.literal("links"), title: z.string(), items: z.array(textLinkSchema).min(1) }),
]);

const snapshotSchema = z.object({
  seo: z.object({ title: z.string().min(1), description: z.string().min(1) }),
  brand: z.object({ name: z.string(), logo: z.string() }),
  topbar: z.array(z.object({ label: z.string(), href: z.string(), value: z.string() })).length(3),
  nav: z.array(textLinkSchema).min(1),
  hero: z.object({ src: z.string(), alt: z.string(), width: z.number(), height: z.number() }),
  intro: z.array(z.string().min(1)).min(1),
  sections: z.array(sectionSchema),
  enquiry: z.object({
    stickyButtonLabel: z.string(),
    whatsappHref: z.string(),
    phoneHref: z.string(),
    formTitle: z.string(),
    fields: z.array(z.object({ id: z.string(), label: z.string() })),
    placeholders: z.array(z.object({ name: z.string(), placeholder: z.string() })),
    submitLabel: z.string(),
    honeypotLabel: z.string(),
  }),
  footer: z.object({
    getInTouch: z.object({ title: z.string(), links: z.array(textLinkSchema) }),
    followUs: z.object({
      title: z.string(),
      links: z.array(z.object({ network: z.string(), href: z.string() })),
    }),
    taxiService: z.object({ title: z.string(), links: z.array(textLinkSchema) }),
    copyright: z.string(),
  }),
});

export type TourCard = z.infer<typeof tourCardSchema>;
export type Destination = z.infer<typeof destinationSchema>;
export type TextLink = z.infer<typeof textLinkSchema>;
type Section = z.infer<typeof sectionSchema>;

export type TourCollection = { title: string; items: TourCard[] };

const withResolvedLinks = <T extends { items: TourCard[] }>(s: T): T => ({
  ...s,
  items: s.items.map((item) => ({ ...item, href: resolveSitePath(item.href) })),
});
export type DestinationGroup = { title: string; items: Destination[] };

const content = snapshotSchema.parse(snapshot);

/** The single-activity tours get their own section; every other priced collection is a package rail. */
const DAY_TOURS_TITLE = "Adventure Day Tours";

function ofKind<K extends Section["kind"]>(kind: K) {
  return content.sections.filter((s): s is Extract<Section, { kind: K }> => s.kind === kind);
}

function requireOne<T>(items: T[], what: string): T {
  const [first] = items;
  if (!first) throw new Error(`Homepage snapshot is missing ${what}. Re-run the sync script.`);
  return first;
}

const cardSections = ofKind("cards");

const placeholders = new Map(content.enquiry.placeholders.map((p) => [p.name, p.placeholder]));
const labels = new Map(content.enquiry.fields.map((f) => [f.id, f.label]));

function fieldText(map: Map<string, string>, key: string): string {
  const value = map.get(key);
  if (!value) throw new Error(`Homepage snapshot is missing form text for "${key}".`);
  return value;
}

export const home = {
  seo: content.seo,
  brand: content.brand,
  nav: content.nav,
  contact: {
    call: content.topbar[0],
    whatsapp: content.topbar[1],
    email: content.topbar[2],
  },
  hero: content.hero,
  intro: content.intro,
  tourCollections: cardSections.filter((s) => s.title !== DAY_TOURS_TITLE).map(withResolvedLinks) satisfies TourCollection[],
  dayTours: withResolvedLinks(
    requireOne(
      cardSections.filter((s) => s.title === DAY_TOURS_TITLE),
      `the "${DAY_TOURS_TITLE}" section`,
    ),
  ) satisfies TourCollection,
  destinationGroups: ofKind("destinations") satisfies DestinationGroup[],
  cabServices: requireOne(ofKind("links"), "the cab services list"),
  enquiry: {
    ...content.enquiry,
    labels: {
      name: fieldText(labels, "your-name"),
      email: fieldText(labels, "your-email"),
      phone: fieldText(labels, "phone-number"),
      date: fieldText(labels, "datepicker"),
      travellers: fieldText(labels, "number-of-people"),
      message: fieldText(labels, "query"),
    },
    placeholders: {
      name: fieldText(placeholders, "your-name"),
      email: fieldText(placeholders, "your-email"),
      phone: fieldText(placeholders, "phone-number"),
      date: fieldText(placeholders, "preferred-date"),
      adults: fieldText(placeholders, "number-of-adults"),
      children: fieldText(placeholders, "number-of-children"),
      message: fieldText(placeholders, "message"),
    },
  },
  footer: content.footer,
} as const;

export type HomeContent = typeof home;
